python3 - <<'EOF'
content = open('project_kickoff.ics').read()
required = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID', 'BEGIN:VEVENT', 'UID:', 'DTSTAMP:', 'DTSTART:', 'DTEND:', 'SUMMARY:', 'END:VEVENT', 'END:VCALENDAR']
missing = [r for r in required if r not in content]
if missing:
    print('INVALID - missing:', missing)
else:
    print('Valid ICS structure')
    # Show parsed event details
    for line in content.splitlines():
        if line.startswith(('SUMMARY', 'DTSTART', 'DTEND', 'UID', 'STATUS')):
            print(line)
EOF

